def is_palindrome(text):
    left, right = 0, len(text) - 1
    while left < right:
        while left < right and not text[left].isalnum():
            left += 1
        while left < right and not text[right].isalnum():
            right -= 1
        if text[left].lower() != text[right].lower():
            return False
        left += 1
        right -= 1
    return True

function isPalindrome(text) {
  let left = 0
  let right = text.length - 1
  const valid = char => /[a-z0-9]/i.test(char)
  while (left < right) {
    while (left < right && !valid(text[left])) left++
    while (left < right && !valid(text[right])) right--
    if (text[left].toLowerCase() !== text[right].toLowerCase()) return false
    left++
    right--
  }
  return true
}

def character_frequency(text):
    frequency = {}
    for character in text:
        if character.isspace():
            continue
        key = character.lower()
        frequency[key] = frequency.get(key, 0) + 1
    return frequency

function characterFrequency(text) {
  const frequency = {}
  for (const character of text) {
    if (/\s/.test(character)) continue
    const key = character.toLowerCase()
    frequency[key] = (frequency[key] ?? 0) + 1
  }
  return frequency
}

def longest_common_prefix(words):
    if not words:
        return ""
    for index, character in enumerate(words[0]):
        for word in words[1:]:
            if index >= len(word) or word[index] != character:
                return words[0][:index]
    return words[0]

function longestCommonPrefix(words) {
  if (words.length === 0) return ''
  for (let index = 0; index < words[0].length; index++) {
    const character = words[0][index]
    for (const word of words.slice(1)) {
      if (index >= word.length || word[index] !== character) {
        return words[0].slice(0, index)
      }
    }
  }
  return words[0]
}

def reverse_words(sentence):
    words = sentence.split()
    words.reverse()
    return " ".join(words)

def run_length_encode(text):
    if not text:
        return ""
    encoded = []
    count = 1
    for index in range(1, len(text)):
        if text[index] == text[index - 1]:
            count += 1
        else:
            encoded.append(text[index - 1] + str(count))
            count = 1
    encoded.append(text[-1] + str(count))
    return "".join(encoded)

function runLengthEncode(text) {
  if (text.length === 0) return ''
  const encoded = []
  let count = 1
  for (let index = 1; index < text.length; index++) {
    if (text[index] === text[index - 1]) count++
    else {
      encoded.push(text[index - 1] + count)
      count = 1
    }
  }
  encoded.push(text[text.length - 1] + count)
  return encoded.join('')
}
